-- M10.ReturnStockIn's "Invoice Details (Return Stock In)" grid on
-- aria:dispatch-vehicle-details gets the new 16-column layout (Billing No /
-- Billing Date / RD Code / Party Name / SKU Name / SKU Code / Reason /
-- Others Reason / Box / PC / Total PC / Billing Rate / Value / Stock
-- Received Rate / Remarks), scoped to M10.ReturnStockIn only via this
-- RepeatingGroup's existing visibleWhen guard -- untouched for every other
-- flow variant on this shared page (in particular M10.TankerInbound's own
-- "invoice_items" RepeatingGroup is not touched by this migration at all).
--
-- Field-name reuse (per confirmed business rule -- no new master table):
--   Billing No   -> invoice_no   (existing column, just relabelled)
--   Party Name   -> vendor_name  (existing column, just relabelled)
--   RD Code      -> rd_code      (existing column, unchanged)
--   SKU Name/Code -> sku_name/sku_code (both already existed since V245;
--     only the INTERACTION direction changes -- SKU Name is now the
--     primary dropdown (SkuMaster, valueField=sku_name), SKU Code
--     auto-fills from it via onChangeFill, row-scoped to the same
--     RepeatingGroup row per registry.js's applyChangeFill/rowScopedTarget.
--
-- Genuinely new fields (added by V305, read by
-- DispatchInvoiceItemTransitionListener as of the accompanying Java change):
--   billing_date, reason, others_reason, box, pc, total_pc, billing_rate,
--   value, stock_received_rate, remarks.
--
-- NOTE: Billing Date / RD Code / Party Name are NOT wired to an auto-fill
-- lookup here -- no confirmed real "Billing No master" data source exists
-- in this codebase (confirmed by inspection: dispatch_invoice_item has no
-- such relationship, and the closest candidates -- billing_entry,
-- billing_order_details, OrderDispatchDetail -- all serve unrelated pages/
-- keys). They render as plain entry fields for now; wiring a real lookup
-- once the actual external-system integration is configured is a follow-up,
-- not guessed at here.
UPDATE page_version pv
JOIN page_definition pd ON pd.current_version_id = pv.id
SET pv.body_json = '{"kind":"layout","schemaVersion":2,"dataSources":[{"id":"dispatchQueue","kind":"rest","method":"GET","url":"/api/workflow/queue-for-page?pageCode=aria:dispatch-vehicle-details&size=200"}],"entity":"DispatchVehicleDetail","layout":[{"kind":"Section","title":"Dispatch Queue (Open)","fields":[{"kind":"WorkflowQueueList","persona":"Dispatch","dataSource":"dispatchQueue","pageSize":25,"cardFields":[],"fillFormOnSelect":true,"priorityShading":true,"secondLineFields":[{"field":"gpNumber","label":""},{"field":"flowVariantCode"}],"fillLookupEntity":"GatePass","fillLookupField":"gp_number","filterFields":[{"field":"vehicleNo","label":"Vehicle No"},{"field":"gpNumber","label":"GP Number"}],"priorityOverrideField":"priority_override"}]},{"kind":"Section","title":"Vehicle & Dispatch Details","fields":[{"kind":"FormField","type":"text","name":"currentUserId","defaultValue":"{{user.username}}","hidden":true},{"kind":"FormField","type":"select","name":"gpNumber","label":"GP Number","required":true,"placeholder":"Select Gate Pass","optionsSource":{"type":"datasource","valueField":"gp_number","labelField":"gp_number","spec":{"type":"entity","entity":"GatePass","select":["id","gp_number","vehicle_no","flow_variant_code","loading_type"],"sort":[{"field":"gp_number","dir":"desc"}]}},"onChangeFill":{"vehicleNo":"vehicle_no","flowVariantCode":"flow_variant_code","loadingType":"loading_type","instanceId":"workflow_instance_id"}},{"kind":"FormField","type":"select","name":"unloadingSupervisor","label":"Unloading Supervisor","optionsSource":{"type":"datasource","spec":{"type":"entity","entity":"Employee","select":["id","employeename"],"filter":{"and":[{"field":"employeetype","op":"eq","value":"Supervisor"},{"field":"status","op":"eq","value":"A"}]},"sort":[{"field":"employeename","dir":"asc"}]},"valueField":"id","labelField":"employeename"},"placeholder":"Select unloading supervisor","visibleWhen":"#form.gpNumber != null && #form.gpNumber != '''' && #form.flowVariantCode 