"}],"rowActions":[{"kind":"Button","label":"🗑️ Delete","action":"repeatingGroup.deleteRow","color":"error","confirmBeforeAction":true}],"footerActions":[{"kind":"Button","label":"+ Add Invoice","action":"repeatingGroup.addRow","color":"secondary"}]},{"kind":"FormField","type":"select","name":"poVerified","label":"PO Verified","options":["YES","NO - MANAGER APPROVAL"],"visibleWhen":"#form.gpNumber != null && #form.gpNumber != '''' && (#form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload'')"},{"kind":"FormField","type":"text","name":"poOverrideReason","label":"Reason (if PO not verified)","visibleWhen":"#form.gpNumber != null && #form.gpNumber != '''' && ((#form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload'') && #form.poVerified != ''YES'')","requiredWhen":"#form.gpNumber != null && #form.gpNumber != '''' && ((#form.flowVariantCode == ''M10.TankerInbound'' || #form.flowVariantCode == ''M10.PackUnload'') && #form.poVerified != ''YES'')"},{"kind":"Grid","name":"returnStockDetailsRow","gap":16,"visibleWhen":"#form.gpNumber != null && #form.gpNumber != '''' && #form.flowVariantCode == ''M10.ReturnStockIn''","style":{"gridTemplateColumns":"repeat(auto-fit, minmax(220px, 1fr))"},"children":[{"kind":"FormField","type":"number","name":"invoiceReturnCount","label":"Invoice Stock Return Count"},{"kind":"FormField","type":"number","name":"boxWeightKg","label":"Box Weight (kg)"},{"kind":"FormField","type":"text","name":"oilType","label":"Oil Type"}]},{"kind":"FormField","type":"select","name":"vehicleNo","label":"Vehicle Number","placeholder":"Auto-filled after GP Number is selected","optionsSource":{"type":"datasource","valueField":"vehicle_no","labelField":"vehicle_no","spec":{"type":"entity","entity":"GatePass","filter":{"field":"status","op":"eq","value":"GATE_PASS_CREATED"},"select":["id","vehicle_no"],"sort":[{"field":"vehicle_no","dir":"asc"}]}},"onChangeFill":{"loadingType":"loading_type"},"disabled":true},{"kind":"FormField","name":"priority_override","type":"text","readOnly":true},{"kind":"FormField","type":"text","name":"loadingType","label":"Vehicle Movement Type","disabled":true},{"kind":"WorkflowActionButton","label":"Save Vehicle Details","action":"workflow.transition","instanceId":"{{form.instanceId}}","trigger":"page.submitted","variant":"primary","workflowCode":"{{form.flowVariantCode}}","visibleWhen":"#form.gpNumber != null && #form.gpNumber != ''''","args":{"formDataPickKeys":["time_taken"]}}]}]}'
